const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = 'debuggableVariants = []';

// `phone/android/` is regenerated by `expo prebuild` and is gitignored, so any
// hand-edit to `android/app/build.gradle` is lost the next time someone runs
// a clean prebuild. The React Native Gradle plugin's default
// `debuggableVariants` is `["debug"]`, which skips embedding the JS bundle
// into the APK for debug builds (fine for `npm run dev`, which connects to a
// live Metro server — but it means a plain `assembleDebug` APK installed
// standalone can't load any script and the app hangs on the native splash
// screen forever, with no crash dialog, since nothing ever paints a first
// frame). This plugin re-inserts `debuggableVariants = []` into the `react {
// ... }` block on every prebuild, so both `assembleDebug` and `assembleRelease`
// embed the bundle and the app actually runs when installed standalone —
// while staying `debuggable=true` so `adb shell run-as` still works for
// development/testing.
function withAndroidDebugBundle(config) {
  return withAppBuildGradle(config, (config) => {
    if (config.modResults.contents.includes(MARKER)) {
      return config;
    }
    const anchor = 'bundleCommand = "export:embed"';
    if (!config.modResults.contents.includes(anchor)) {
      throw new Error(
        `withAndroidDebugBundle: could not find anchor "${anchor}" in android/app/build.gradle — the react {} block may have changed shape.`
      );
    }
    config.modResults.contents = config.modResults.contents.replace(
      anchor,
      `${anchor}\n    ${MARKER}`
    );
    return config;
  });
}

module.exports = withAndroidDebugBundle;
